/*
 * zx_ffe_table.h — FFE (Fast-ForwardEngine) extract infrastructure for the
 * ZTE H3600 CLA classifier. Phase 6 HW flow-offload.
 *
 * This is the one-time extract setup that the STOCK tm.ko writes via
 *   tm_acl_l2_fast_init     (tm.c:49785)  -> ram1 rules (p<<4)+0..3, p=1..8
 *   tm_acl_3tuple_fast_init (tm.c:54578)  -> ram1 rules (0x14+0x10*(p-1))+0..3, p=1..9
 *   tm_acl_fast_init        (tm.c:54140)  -> ram1 rules 0x90/0x91 (v4 5-tuple),
 *                                            0x02/0x03 (v6 5-tuple)
 * plus the ram0 extract-index tables (idx 1..10) set up by aclRamInit_part_6
 * (tm.c:54704) and enabled (index_valid bits in word4) by the inits above.
 *
 * Mainline never ran these, so ram0[0x09]/ram1[0x9x] read all-zeros and the
 * CLA could not fast-classify -> every routed flow trapped to the CPU
 * (the long-standing "CLA traps all" deadend). This table is the port.
 *
 * The fast-ENABLE is NOT a separate register: it is the per-index index_valid
 * mask (word4 bits, EN_V4/V6FAST_EXTIDXTBL tm.c:49717/49751) baked into each
 * ram0 entry here (e.g. ram0[0x09] word4 0x00150051 -> v4-5tuple|v4-3tuple|
 * v6-3tuple valid). g_ipv4FastEn/g_ipv6FastEn are SW flags only (they steer
 * aclGetExtIdxRuleRamAddrByPort to return idx 9 / 10); the HW gate is word4.
 *
 * Every entry below was VERIFIED byte-exact against the live stock CLA dump
 * tasks/00.10.02.re-stock-kmods/findings/captures/cla_stock/cla_stock_ram0-6_2026-06-01.txt
 * (0 mismatches). The v4 5-tuple rule 0x90/0x91 + index 9 also match the
 * HW-validated ground truth in findings/phase6_cla_hw_hash_CRACKED.md.
 *
 * Regenerate / re-verify:
 *   python3 tasks/00.01.eth-driver/scripts/ffe_gen_table.py \
 *       --emit linux-v6.6/drivers/net/ethernet/zte/zx_ffe_table.h
 *
 * Write protocol: ALL CLA indirect rams are CMD-first + DESCENDING data
 * (zx_cla_write_hash). ram1 = 17 words, ram0 = 5 words.
 *   ram1 rule  -> zx_cla_write_hash(e, 1, id,  w, 17)
 *   ram0 index -> zx_cla_write_hash(e, 0, id,  w, 5)
 */

